import{_ as o,a0 as n,w as l,s as p,I as i,x as a,a1 as r,A as t,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"如何在 Fedora Linux 上安装 Brave 浏览器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora Linux 上安装 Brave 浏览器 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora Linux 上安装 Brave 浏览器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora Linux 上安装 Brave 浏览器 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211119 How to Install Brave Browser on Fedora, Red Hat - CentOS","title":"如何在 Fedora Linux 上安装 Brave 浏览器","tag":"202111","desc":""},"relativePath":"202111/20211119 How to Install Brave Browser on Fedora, Red Hat - CentOS.md","filePath":"[post].md"}'),u={name:"202111/20211119 How to Install Brave Browser on Fedora, Red Hat - CentOS.md"};function b(g,e,h,m,f,v){const s=n("Link");return l(),p("div",null,[e[19]||(e[19]=i("h1",{id:"如何在-fedora-linux-上安装-brave-浏览器",tabindex:"-1"},[a("如何在 Fedora Linux 上安装 Brave 浏览器 "),i("a",{class:"header-anchor",href:"#如何在-fedora-linux-上安装-brave-浏览器","aria-label":"Permalink to “如何在 Fedora Linux 上安装 Brave 浏览器”"},"​")],-1)),e[20]||(e[20]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/28/102349idh316xz3bslr6ps.jpg",alt:""})],-1)),i("p",null,[r(s,{href:"https://brave.com/"},{default:t(()=>[...e[0]||(e[0]=[a("Brave",-1)])]),_:1}),e[2]||(e[2]=a(" 是一个越来越 ",-1)),r(s,{href:"https://itsfoss.com/best-browsers-ubuntu-linux/"},{default:t(()=>[...e[1]||(e[1]=[a("流行于 Linux",-1)])]),_:1}),e[3]||(e[3]=a(" 和其他操作系统的网页浏览器。对默认情况下阻止广告和跟踪的关注，以及对 Chrome 扩展的支持，使 Brave 成为 Linux 用户的热门选择。",-1))]),e[21]||(e[21]=d('<p>在本教程中，你将学习如何在 Fedora Linux 上安装 Brave。你还将学习如何更新和删除它。</p><p>本教程已经在 Fedora 上进行了测试，但它也应该适用于基于 Red Hat 的其他发行版，如 CentOS、Alma Linux 和 Rocky Linux。</p><h3 id="在-fedora-linux-上安装-brave-浏览器" tabindex="-1">在 Fedora Linux 上安装 Brave 浏览器 <a class="header-anchor" href="#在-fedora-linux-上安装-brave-浏览器" aria-label="Permalink to “在 Fedora Linux 上安装 Brave 浏览器”">​</a></h3><p>你需要在这里用命令行的方式来安装 Brave。</p><p>作为先决条件，请确保 <code>dnf-plugin-core</code> 已经安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install dnf-plugins-core</span></span></code></pre></div><p>下一步是将 Brave 仓库添加到你的系统中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf config-manager --add-repo https://brave-browser-rpm-release.s3.brave.com/x86_64/</span></span></code></pre></div><p>你还应该导入并添加仓库密钥，这样你的系统就会信任来自这个新添加的仓库的软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rpm --import https://brave-browser-rpm-release.s3.brave.com/brave-core.asc</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/adding-Brave-browser-repository-in-Fedora.png?resize=800%2C300&amp;ssl=1" alt="Adding Brave Browser repository in Fedora Linux"></p><p>现在可以开始了。用这个命令安装 Brave：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install brave-browser</span></span></code></pre></div><p><strong>当被要求确认你的选择时按 <code>Y</code></strong>。根据你的网速，这应该需要几秒钟或几分钟的时间。如果 DNF 的缓存最近没有更新，甚至可能需要更长时间。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/Installing-Brave-Browser-Fedora.png?resize=800%2C428&amp;ssl=1" alt="Installing Brave Browser in Fedora"></p><p>安装完成后，在系统菜单中寻找 Brave 并从那里启动。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/start-brave-fedora-linux.png?resize=759%2C219&amp;ssl=1" alt="Start Brave browser in Fedora Linux"></p><h3 id="在-fedora-linux-上更新-brave-浏览器" tabindex="-1">在 Fedora Linux 上更新 Brave 浏览器 <a class="header-anchor" href="#在-fedora-linux-上更新-brave-浏览器" aria-label="Permalink to “在 Fedora Linux 上更新 Brave 浏览器”">​</a></h3><p>你已经为浏览器添加了一个仓库，并且导入了它的密钥。你的系统信任来自这个仓库的软件包。</p><p>因此，当有新的 Brave 浏览器发布并提供给这个仓库时，你会通过常规的系统升级得到它。</p><p>换句话说，你不需要做任何特别的事情。只要保持你的 Fedora 系统更新，如果有 Brave 的新版本，它应该会随着系统更新自动安装。</p><h3 id="从-fedora-linux-中删除-brave-浏览器" tabindex="-1">从 Fedora Linux 中删除 Brave 浏览器 <a class="header-anchor" href="#从-fedora-linux-中删除-brave-浏览器" aria-label="Permalink to “从 Fedora Linux 中删除 Brave 浏览器”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/Brave-Browser-in-Fedora-Linux.png?resize=800%2C530&amp;ssl=1" alt="Brave Browser in Fedora Linux"></p><p>如果你因为某些原因不喜欢 Brave，你可以从你的系统中删除它。只需使用 <code>dnf remove</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf remove brave-browser</span></span></code></pre></div><p>当询问时按 <code>Y</code>：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/removing-Brave-browser-Fedora-Linux.png?resize=800%2C399&amp;ssl=1" alt="Removing Brave browser from Fedora Linux"></p><p>你也可以选择禁用 <code>brave-browser-rpm-release.s3.brave.com_x86_64_.repo</code> 或者从 <code>/etc/yum/repos.d</code> 中完全删除这个文件，虽然这并不是必须的。</p><p>我希望这个快速提示对你有帮助。如果你有任何问题或建议，请让我知道。</p><hr>',30)),i("p",null,[e[5]||(e[5]=a("via: ",-1)),r(s,{href:"https://itsfoss.com/install-brave-browser-fedora/"},{default:t(()=>[...e[4]||(e[4]=[a("https://itsfoss.com/install-brave-browser-fedora/",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=a("作者：",-1)),r(s,{href:"https://itsfoss.com/author/abhishek/"},{default:t(()=>[...e[6]||(e[6]=[a("Abhishek Prakash",-1)])]),_:1}),e[11]||(e[11]=a(" 选题：",-1)),r(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[7]||(e[7]=[a("lujun9972",-1)])]),_:1}),e[12]||(e[12]=a(" 译者：",-1)),r(s,{href:"https://github.com/geekpi"},{default:t(()=>[...e[8]||(e[8]=[a("geekpi",-1)])]),_:1}),e[13]||(e[13]=a(" 校对：",-1)),r(s,{href:"https://github.com/wxy"},{default:t(()=>[...e[9]||(e[9]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[16]||(e[16]=a("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[14]||(e[14]=[a("LCTT",-1)])]),_:1}),e[17]||(e[17]=a(" 原创编译，",-1)),r(s,{href:"https://linux.cn/"},{default:t(()=>[...e[15]||(e[15]=[a("Linux中国",-1)])]),_:1}),e[18]||(e[18]=a(" 荣誉推出",-1))])])}const c=o(u,[["render",b]]);export{B as __pageData,c as default};
